  const [selectedDate, setSelectedDate] = useState<DateTime | null>(null);

  return (
    <div style={{ padding: 24, maxWidth: 320 }}>
      <DatePicker
        value={selectedDate}
        onUpdate={setSelectedDate}
        placeholder="Выберите дату"
      />
    </div>
  );
}

